class AccountSharing {
  public String solve(List<List<String>> connections) {
    Set<String> seen = new HashSet<>();
    for (List<String> conn : connections) {
      String username = conn.get(0);
      String ip = conn.get(1);
      if (seen.contains(username)) {
        return ip;
      }
      seen.add(username);
    }
    return "";
  }
}

